$\begin{array}{lr}
\mathrm{Na}_{2} \mathrm{~S}+\mathrm{nS}(\mathrm{n}=1-8) & \rightarrow(\mathrm{X}) \\
\mathrm{Na}_{2} \mathrm{SO}_{3}+\mathrm{S} & \rightarrow(\mathrm{Y})
\end{array}
$\begin{array}{ll}(\mathrm{X}) & (\mathrm{Y})\end{array}

